# Step 1: Authenticate with Kuvio and obtain token import requests import json import logging
logger = logging.getLogger(__name__) Remote = self.remote_id
try: connection_params = json.loads(Remote.connection_params or '{}') except Exception: connection_params = {}
base_url = (Remote.base_url or '').strip() username = connection_params.get('username', '') password = connection_params.get('password', '')
if not base_url: raise Exception('Kuvio base URL not configured in URL Base field')
if not username or not password: raise Exception('Kuvio credentials (username/password) not configured in connection_params')
login_url = '%s/auth/login' % base_url payload = { 'username': username, 'password': password }
try: response = requests.post(login_url, json=payload, timeout=30) response.raise_for_status() except requests.exceptions.RequestException as e: error_msg = 'Kuvio login failed: %s' % str(e) logger.error(error_msg) raise Exception(error_msg)
try: response_data = response.json() token = response_data.get('token') if not token: raise Exception('No token in login response') except (ValueError, KeyError) as e: error_msg = 'Failed to parse Kuvio login response: %s' % str(e) logger.error(error_msg) raise Exception(error_msg)
bag['kuvio_token'] = token bag['base_url'] = base_url logger.info('Kuvio: Login successful, token obtained')

# Step: Get list of devices from Kuvio import requests import json import logging import base64
logger = logging.getLogger(__name__) Remote = self.remote_id
# Get token from bag if available (from login step), or authenticate fresh token = bag.get('kuvio_token') base_url = (bag.get('base_url') or Remote.base_url or '').strip()
if not token or not base_url: # Need to authenticate first try: connection_params = json.loads(Remote.connection_params or '{}') except Exception: connection_params = {}
base_url = (Remote.base_url or '').strip() username = connection_params.get('username', '') password = connection_params.get('password', '')
if not base_url: raise Exception('Kuvio base URL not configured in URL Base field')
if not username or not password: raise Exception('Kuvio credentials not configured')
login_url = '%s/auth/login' % base_url try: response = requests.post(login_url, json={'username': username, 'password': password}, timeout=30) response.raise_for_status() response_data = response.json() token = response_data.get('token') if not token: raise Exception('No token in login response') except Exception as e: raise Exception('Kuvio authentication failed: %s' % str(e))
bag['kuvio_token'] = token bag['base_url'] = base_url
# Get customer_id from user info user_url = '%s/auth/user' % base_url headers = {'Authorization': 'Bearer %s' % token}
try: response = requests.get(user_url, headers=headers, timeout=30) response.raise_for_status() response_data = response.json() customer_id = response_data.get('customerId')
# Kuvio may return customerId as UUID string or as object {'id': 'uuid', ...} if isinstance(customer_id, dict): customer_id = customer_id.get('id')
if customer_id is not None: customer_id = str(customer_id)
if not customer_id: raise Exception('No customerId in user response') logger.info('Kuvio: /auth/user resolved customer_id=%s', customer_id) except Exception as e: status_code = getattr(response, 'status_code', None) if 'response' in locals() else None response_text = '' if 'response' in locals(): try: response_text = response.text or '' except Exception: response_text = '' response_text = response_text[:500] raise Exception('Failed to get customer ID: %s (status=%s, body=%s)' % ( str(e), status_code, response_text))
bag['customer_id'] = customer_id
# Now get devices list page_size = 100 page = 0 has_next = True devices = [] api_total_pages = 0 api_total_elements = 0 pages_fetched = 0 devices_url = ''
try: while has_next: devices_url = '%s/customer/%s/devices?pageSize=%d&page=%d' % ( base_url, customer_id, page_size, page) response = requests.get(devices_url, headers=headers, timeout=30) response.raise_for_status() response_data = response.json()
if isinstance(response_data, dict): page_devices = response_data.get('data') or response_data.get('items') or [] api_total_pages = response_data.get('totalPages') or api_total_pages api_total_elements = response_data.get('totalElements') or api_total_elements has_next_value = response_data.get('hasNext') if has_next_value is None: if api_total_pages: has_next = (page + 1) < int(api_total_pages) else: has_next = len(page_devices) == page_size else: has_next = bool(has_next_value) elif isinstance(response_data, list): page_devices = response_data has_next = False else: page_devices = [] has_next = False
if not isinstance(page_devices, list): raise Exception('Invalid devices payload type: %s' % type(page_devices).__name__)
devices.extend(page_devices) pages_fetched += 1
if has_next: page += 1 if page > 10000: raise Exception('Pagination safety limit reached while fetching devices') except Exception as e: status_code = getattr(response, 'status_code', None) if 'response' in locals() else None response_text = '' if 'response' in locals(): try: response_text = response.text or '' except Exception: response_text = '' response_text = response_text[:500] raise Exception('Kuvio get devices failed: %s (url=%s, page=%s, status=%s, body=%s)' % ( str(e), devices_url, page, status_code, response_text))
# Build filtered device list and map devices_filtered = [] devices_map = {} for device in devices: if not isinstance(device, dict): continue
device_id_block = device.get('id') device_name = device.get('name')
# Kuvio may return nested identifiers as objects {'id': 'uuid', ...} device_id = device_id_block if isinstance(device_id_block, dict): device_id = device_id_block.get('id')
if device_id is not None: device_id = str(device_id)
if device_id: filtered_device = { 'id': device_id_block, 'name': device_name, } devices_filtered.append(filtered_device) devices_map[device_id] = filtered_device
bag['devices'] = devices_filtered bag['devices_map'] = devices_map
payload = { 'procedure': 'Kuvio: Get Devices', 'executed_at': fields.Datetime.now(), 'summary': { 'total_devices': len(devices), 'total_indexed_devices': len(devices_map), 'customer_id': customer_id, 'total_pages': api_total_pages, 'total_elements': api_total_elements, 'pages_fetched': pages_fetched, }, 'devices': devices_filtered, }
json_str = json.dumps(payload, ensure_ascii=False, indent=2) encoded = base64.b64encode(json_str.encode('utf-8')) timestamp = fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_') fname = 'kuvio_devices_%s.json' % timestamp
att = env['ir.attachment'].create({ 'name': fname, 'datas_fname': fname, 'datas': encoded, 'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': Remote.id })
Remote.message_post( body='[KUVIO] Devices=%s - JSON generated for import/setup' % len(devices), attachment_ids=[att.id] )
bag['attachment_id'] = att.id bag['attachment_name'] = fname result = 'Kuvio get devices OK - %d devices. File: %s' % (len(devices), fname) logger.info('Kuvio: Got %d devices across %d pages', len(devices), pages_fetched)

# Step 3: Create sensor plan for devices (builds configuration for Get Readings)
import json
import logging
from datetime import datetime

logger = logging.getLogger(__name__)
Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']

# Get all sensors configured for Kuvio
sensors = Sensor.search([
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
    ('active', '=', True),
])

logger.info('Kuvio: [CreateSensorPlan] Building sensor plan from %d sensors', len(sensors))

sensor_plan = []
for sensor in sensors:
    device = sensor.device_id

    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}

    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

    key = sensor_cfg.get('sensor_id') or sensor_cfg.get('key')
    device_id = device_cfg.get('device_id')
    start_date = device_cfg.get('start_date')

    if device_id is not None:
        device_id = str(device_id)

    if not key or not device_id:
        logger.warning('Kuvio: [CreateSensorPlan] Sensor %s missing required config (key=%s, device_id=%s)',
                      sensor.id, key, device_id)
        continue

    plan_item = {
        'odoo_sensor_id': sensor.id,
        'key': key,
        'device_id': device_id,
        'start_date': start_date
    }
    sensor_plan.append(plan_item)
    logger.debug('Kuvio: [CreateSensorPlan] Added to plan: sensor_id=%s, device_id=%s, key=%s, start_date=%s',
                sensor.id, device_id, key, start_date)

bag['sensor_plan'] = sensor_plan
logger.info('Kuvio: [CreateSensorPlan] Sensor plan built with %d items ready for telemetry queries', len(sensor_plan))
result = 'Sensor plan built - %d sensors configured' % len(sensor_plan)
